const API='https://script.google.com/macros/s/AKfycbxiBZgw7zebOv_V1h7Xvt_7fTDxZUQUyPsN5Wk9ysb4CClOhSveLUONxq0pyE6wvQXN/exec';
const wall=document.getElementById('wall'),w=wall.getContext('2d'),statusEl=document.getElementById('status'),countEl=document.getElementById('count');let marks=[];
const slots=[[150,120],[430,105],[720,135],[1030,100],[1320,130],[1620,110],[210,275],[520,245],[780,290],[1110,250],[1430,285],[1660,260],[170,455],[410,520],[1400,455],[1640,515],[145,690],[390,650],[1410,675],[1650,635],[170,870],[440,830],[710,900],[1080,855],[1360,900],[1620,850],[300,1050],[650,1015],[1190,1045],[1540,1020]];
const norm=n=>(n||'').trim().replace(/\s+/g,' ').toLowerCase();function uniqueMarks(list){const seen=new Set();return(list||[]).filter(m=>{const k=norm(m.name);if(!k||seen.has(k))return false;seen.add(k);return true})}
function hash(str){let h=2166136261;for(const ch of str){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}function rand(seed){let t=seed+0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}
function base(){w.fillStyle='#f8f3e9';w.fillRect(0,0,1800,1200);w.textAlign='center';w.fillStyle='#171b3d';w.font='900 118px Arial';w.fillText('INF 125',900,535);w.font='900 94px Arial';w.fillText('AI LITERACY',900,639);w.font='italic 43px Georgia';w.fillText('Curious People. Build Brighter Futures.',900,708);w.strokeStyle='#6d3fd6';w.lineWidth=8;w.beginPath();w.moveTo(690,745);w.quadraticCurveTo(900,705,1120,738);w.stroke();w.textAlign='left';w.font='700 22px Arial';w.fillText('DIFFERENT PEOPLE.',70,1115);w.fillText('SHARED JOURNEY.',70,1145);w.fillText('LASTING IMPACT.',70,1175);w.textAlign='right';w.font='800 34px Arial';w.fillText('NKU  |  FALL 2026',1730,1145)}
function bounds(st){let minX=1,minY=1,maxX=0,maxY=0;st.flat().forEach(p=>{minX=Math.min(minX,p.x);minY=Math.min(minY,p.y);maxX=Math.max(maxX,p.x);maxY=Math.max(maxY,p.y)});return{minX,minY,w:Math.max(.05,maxX-minX),h:Math.max(.05,maxY-minY)}}
function drawMark(m,i){if(!m.strokes?.length||!slots[i])return;const[cx,cy]=slots[i],b=bounds(m.strokes),aspect=b.w/b.h,seed=hash((m.name||'mark')+i),scale=.82+rand(seed+33)*.55;let dw=Math.min(300,Math.max(150,aspect*88))*scale,dh=dw/aspect;if(dh>135){dh=135;dw=dh*aspect}w.save();w.translate(cx+(rand(seed)-.5)*34,cy+(rand(seed+9)-.5)*32);w.rotate((-9+rand(seed+27)*18)*Math.PI/180);w.strokeStyle=m.color||'#17214c';w.lineWidth=6;w.lineCap='round';w.lineJoin='round';for(const line of m.strokes){w.beginPath();line.forEach((p,j)=>{const x=((p.x-b.minX)/b.w-.5)*dw,y=((p.y-b.minY)/b.h-.5)*dh;j?w.lineTo(x,y):w.moveTo(x,y)});w.stroke()}w.restore()}
function render(){base();marks.slice(0,30).forEach(drawMark);countEl.textContent=marks.length}
async function load(){try{const r=await fetch(API+'?action=list&_='+Date.now(),{cache:'no-store'}),text=await r.text();if(!r.ok)throw Error('Server '+r.status);const data=JSON.parse(text);if(!data.ok)throw Error(data.error||'Load failed');marks=uniqueMarks(data.signatures||[]);render();statusEl.textContent='Live · '+marks.length+' unique signatures'}catch(e){statusEl.textContent='Reconnecting…'}}
render();load();setInterval(()=>{if(!document.hidden)load()},2500);